import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第117章 发货清单","description":"","frontmatter":{},"headers":[],"relativePath":"第117章_发货清单.md","filePath":"第117章_发货清单.md"}'),_={name:"第117章_发货清单.md"};function r(u,p,s,n,q,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第117章-发货清单" tabindex="-1">第117章 发货清单 <a class="header-anchor" href="#第117章-发货清单" aria-label="Permalink to &quot;第117章 发货清单&quot;">​</a></h1><p>十点四十七，她发来一张发货清单。</p><p>她那边的十点四十七，我这边下午两点四十七。</p><p>距她下线五十四分钟。</p><p>那张表是这样的：</p><p>订单号，品名，数量，地址后四位，备注。</p><p>一共三十八行。</p><p>前面三十六行是十一月的旧单。</p><p>最后两行是新的。</p><p>第三十七行：立牌，2，收件人代号 4471，备注&quot;补发&quot;。</p><p>第三十八行：小卡一套，1，收件人代号 8802，备注&quot;这个我这边发货不了，你那边拆两个包，一个包发不了就退我，我下周处理&quot;。</p><p>她在这张表下面发了一句话。</p><p>她说：这两单我今天处理不了，我今天有课。</p><p>她说：你按这个发。</p><p>她说：38 号那个客人昨天问过一次，你先发。</p><p>她说：发完你把单号打上来。</p><p>我说：好。</p><p>她说：另外，去年那个退件的十九块，我这边一直没给你算。</p><p>我说：那不用。</p><p>她说：不是用不用。</p><p>她说：那是我们两个的账。</p><p>她说：我今天把它算清是因为我今年不再跟你算账了。</p><p>她说：我要是今天不算，你以后每一次发货都会想着这十九块。</p><p>她说：我不想要这样。</p><p>我说：那你转我。</p><p>她说：我转了。</p><p>我说：收到了。</p><p>她说：好。</p><p>她说：那就这样。</p><p>我说：那就这样。</p><p>那天下午两点四十七到五点十一，我发了十九个件。</p><p>我把那张清单打印出来。</p><p>我拿着那张纸去驿站。</p><p>那个驿站那个小伙子不在，换了一个女的。</p><p>她说，你这一堆都是今天发？</p><p>我说，对。</p><p>她说，你这一单有两个是退回件，你要不要看一下里面东西齐不齐。</p><p>我说，我看看。</p><p>我在驿站那个台子上把那两个退回件拆开。</p><p>我看了。</p><p>齐。</p><p>我重新装好，贴单。</p><p>我那天下午发完，五点多我在驿站外面站着。</p><p>那个驿站门口有一块水泥地，边上被人堆了一排坏的塑料筐。</p><p>我站在那里抽了一支烟。</p><p>我不抽烟。我那天在背包里找到了那年她给我的那半包，我拿出来抽了一支。</p><p>我拿手机看那张清单。</p><p>三十八行。</p><p>我看到第三十七行那个&quot;补发&quot;。</p><p>那个立牌是那年二月那个二十四块的立牌。</p><p>那个客人要了两次。</p><p>我那天下午把那一件发出去了。</p><p>我发出去的时候我心里想的是另一件事。</p><p>我想的是今天早上她讲&quot;我这六年第一次觉得我这一天是自己的&quot;。</p><p>她讲完那句话二十分钟以后，她给我发了一张发货清单。</p><p>这两件事不矛盾。</p><p>她那一天是自己的，方式是：她把该交代的交代完。</p><p>她这六年里所有告别都是这个形状。</p><p>她把事情分干净，然后她走。</p><p>那天晚上我八点给她发了一条。</p><p>我说：38 号我发了两个包，一个单号我打错了，重打。</p><p>她九点回：好。</p><p>我说：那个客人问什么时候到。</p><p>她说：你说明天。</p><p>我说：好。</p><p>那天我们讲了四条。</p><p>四条里没有一条是今天早上那五十七分钟里的。</p><p>那天夜里我在本子上写了一件事。</p><p>我写：她今天早上八点十二讲&quot;我基本上并不喜欢你&quot;。</p><p>我写：她十点四十七发了一张三十八行的发货清单。</p><p>我写：中间隔了五十四分钟。</p><p>我写：我这六年里从来没有像今天这样，觉得这两件事是同一件。</p><p>我写：她把交代当告别，我把告别当账。</p><p>我写：我们两个今天早上都把自己这辈子最熟的那一样东西拿出来了。</p><p>我写：她拿出来的是清单。</p><p>我写：我拿出来的是那个删干净的输入框。</p><p>后来那一年二月五号这一天，我一共留下三样东西。</p><p>一张十六页的打印稿，左她右我。</p><p>一份 8 KB 的 xlsx，第三张表下面我划了一道，写了一个&quot;记&quot;。</p><p>和三十八行的发货清单。</p><p>那张清单我留在桌上。</p><p>那天夜里我把它跟&quot;你要记的&quot;那张表并排放好。</p><p>我放在桌上，不是抽屉。</p><p>我那天把它放在桌上，是为了让我每天早上起来，我要绕开它才能放钥匙。</p><p>我那天决定我不再往抽屉里放东西。</p><p>我这辈子把最要紧的几样东西全部塞进抽屉，因为我知道我不会天天开。</p><p>那天晚上七点四十，我做了一件事。</p><p>我把那个备忘录打开了。</p><p>那个备忘录里存着我这四年没发出去的东西。</p><p>一共三十一条。</p><p>我一条一条往下拉。</p><p>拉到第七条我停了。</p><p>第七条是那年十二月十九写的。</p><p>那一条只有一行：今天她妈把那个卡给她了，我不知道该讲什么。</p><p>我那天在她妈给卡的那个晚上，没有讲一个字。</p><p>我拉到第二十三条。</p><p>第二十三条是今天早上八点四十四。</p><p>那一条写的是：我今天早上八点十二的第一个念头不是疼，是我今天终于可以不用等了。</p><p>我那天删了两遍。</p><p>我删的是输入框里的字。</p><p>但是我在备忘录里存了一份。</p><p>我今天早上存那一份的时侯，我自己都不知道我在存。</p><p>我坐在那把椅子上，看着那二十三条。</p><p>我那天晚上把那个备忘录关掉了。</p><p>我没有删。</p><p>我今年冬天十四个压缩包全部倒进那 41 个 G 的时候，我把那个备忘录也倒进去了。</p><p>它最后进去了。</p><p>可是它一开始不在那个本子里，也不在她那边。</p><p>它在我一个从来不给任何人看的软件里。</p><p>那天我把它们放在一起。</p><p>我那天晚上十一点四十分，给她发了最后一条。</p><p>我说：你今天那个包拆了，你把那根绳子给我。</p><p>她隔了特别久。</p><p>她回的是：你要绳子干什么。</p><p>我说：我不知道。</p><p>我说：我今天看见你那个备注里写绳子，我想要那个东西在我这儿。</p><p>她说：我在网上十块钱一根。</p><p>我说：那你买十块的。</p><p>她说：好。</p><p>她说：明天我下单，我写你那边的地址。</p><p>我说：好。</p><p>那根绳子到了以后，我放在抽屉里。</p><p>我把它放在了那张瓶签旁边。</p><p>两个东西碰在一起，没有声音。</p><p>我那天讲我不再往抽屉里放东西。</p><p>我那天晚上就把一根绳子放进了抽屉。</p><p>我这个人我这辈子讲得最顺的一句话，是明天不这么过了。</p><p>那天我把它们放在桌上。</p><p>我放在桌上是为了让我每天早上起来，我要绕开它们才能放钥匙。</p>',129)])])}const l=t(_,[["render",r]]);export{d as __pageData,l as default};
